"""Reviewed apple-sauce formulas, retaining source ratios and modern storage."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
db=sqlite3.connect(root.parent.parent/'outputs/SavorShelf-Content-Repairs/grouped-work.sqlite3')
def original(id):return json.loads(db.execute('select record from recipes where id=?',(id,)).fetchone()[0])
records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
merges={'historical-82e320669c43ba1739da325c':'historical-0c9d698dd3306b18d84fa64b','historical-7bd978afa10cc767d08bbc82':'historical-3857f5cc1674d352c0a9c599','historical-439746b772648b266aa7b551':'historical-6b93e1af8b5be685d56e023e','historical-8b215e30528bf0bf51321ec5':'historical-6b93e1af8b5be685d56e023e','historical-5cba2b0a8836eefac7acf407':'historical-95cac5255f40f3aedaa6c86a'}
newids=[]
def ing(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def apples(a):return ing('apples',a,'g','tart apples, weighed after peeling and coring','Use the same prepared weight of another cooking apple; sweetness and the time needed to soften will vary.')
def water(a):return ing('water',a,'ml','drinking water','Use the same volume of unsweetened apple juice for a sweeter sauce with a different flavor.')
def sugar(a):return ing('sugar',a,'g','granulated sugar','Reduce to taste for a less sweet sauce; this is a refrigerated food, not a shelf-stable preserve.')
def butter(a):return ing('butter',a,'g','unsalted butter','Use the same weight of a dairy-free butter alternative, or omit for a less rich sauce.')
def add(id,title,n,minutes,desc,items,steps,notes):
 s=original(id);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Sauces',servings=n,yieldUnit='sauce portions',minutes=minutes,totalMinutes=minutes,ingredients=items,steps=steps+['Serve warm, or transfer to shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder. Freeze portions for longer storage. This is not a canning recipe.'],sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T14:00:00Z',notes=notes+' Missing amounts, portion yields and timings are disclosed modern estimates, not exact recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking time or temperature.',source=s['recipe']['source']+' SavorShelf measured adaptation. Apple preparation and simmering reference: https://extension.rutgers.edu/recipes/applesauce')
 r.pop('variants',None);r['sourceAliases']=[old for old,new in merges.items() if new==id]
 for old in r['sourceAliases']:r['source']+=' Equivalent source retained: '+original(old)['recipe']['source']
 records[id]={'sourceId':id,'bodySha256':s['bodySha256'],'recipe':r};newids.append(id)
 return r
def simmer():return ['Cut {{apples}} into roughly 2 cm pieces. Put them in a heavy saucepan with {{water}}.','Bring just to a boil, cover and lower the heat. Simmer for 15–25 minutes, stirring frequently, until the apples collapse easily under a spoon. Add a small splash of water only if the pan begins to dry.','Mash the apples with a potato masher, or press through a sieve for a smoother sauce.']
add('historical-0c9d698dd3306b18d84fa64b','Apple Sauce with Butter',8,35,'Tart apples are simmered and mashed, then finished with butter and a little sugar for a smooth accompaniment.',[apples(900),water(120),butter(15),sugar(40)],simmer()+['Stir {{butter}} and {{sugar}} into the hot mashed apples until melted and dissolved.'],'Two six-apple sources have the same butter-and-sugar finish. Prepared apple weight replaces variable fruit size. Water is increased from the Abbott source spoonful to a practical 120 ml to limit scorching; the Beeton source gives no fixed water quantity. Both sources are retained.')
add('historical-3857f5cc1674d352c0a9c599','Unsweetened Apple Sauce',6,30,'Apples and water cook down to a simple mashed sauce with no added sugar or fat.',[apples(750),water(150)],simmer(),'The two reviewed sources share only apples and water, simmered and mashed. Missing quantities are supplied; no sugar, spice or fat has been added. Tartness depends on the apples.')
add('historical-7383481118b1704589f9aa12','Apple Sauce Victoria with Vanilla',8,35,'A smooth, sieved apple sauce is lightly sweetened and finished with vanilla.',[apples(1000),water(200),sugar(60),ing('vanilla',5,'ml','vanilla extract','Use 2 g finely grated lemon zest for a different flavor, or omit.')],simmer()+['Press the mashed apples through a fine sieve if they are not already smooth. Stir in {{sugar}} until dissolved, then stir in {{vanilla}} off the heat.'],'The source vanilla teaspoon becomes 5 ml. Apple, water and sugar amounts are supplied. A controlled simmer replaces the very brisk boil to reduce scorching while retaining the smooth texture.')
add('historical-7d66caf84ba2fcfbd949b5cf','Spiced Apple Sauce with Butter',8,65,'Apples cook into a thick sauce with clove and cinnamon, then receive a butter-and-sugar finish.',[apples(900),water(240),butter(28),sugar(60),ing('cloves',.5,'g','ground cloves','Omit for a milder sauce; there is no identical substitute.'),ing('cinnamon',2,'g','ground cinnamon','Use 1 g ground allspice for a different spice profile, or omit.')],['Cut {{apples}} into 2 cm pieces and put in a heavy saucepan with {{water}}, {{cloves}} and {{cinnamon}}.','Bring to a gentle simmer, partly cover and cook for about 45 minutes, stirring often and mashing as the apples soften. Add water in small splashes if needed to stop the bottom catching.','Press through a coarse sieve. Return to the pan, add {{sugar}} and {{butter}}, and simmer gently for another 5 minutes, stirring until smooth.'],'The source long simmer and butter finish remain. Ground clove and cinnamon quantities are modern choices in place of grinding four cloves and an unspecified stick. Six variable apples become 900 g prepared fruit.')
add('historical-6b93e1af8b5be685d56e023e','Enkelt Äppelmos (Sweet Lemon Apple Sauce)',16,45,'A sweet, thick apple sauce retains the source ratio of one part sugar to two parts prepared apple, with lemon juice and zest.',[apples(1000),water(200),sugar(500),ing('lemon',15,'ml','lemon juice','Use the same volume of lime juice for a different citrus flavor.'),ing('zest',1,'g','finely grated lemon zest, yellow part only','Use the same weight of orange zest, or omit.')],['Cut {{apples}} into small pieces and put in a heavy saucepan with {{water}}, {{sugar}}, {{lemon}} and {{zest}}.','Warm gently, stirring until the sugar dissolves. Simmer over low heat for 25–35 minutes, stirring frequently along the bottom, until the apples break down to a thick pulp. Add a little water only if needed to prevent scorching.','Mash thoroughly or pass through a sieve. If too thin, simmer uncovered for a few more minutes while stirring.'],'Three equivalent transcriptions are consolidated. The half-weight sugar ratio is retained in a smaller batch; the ambiguous apple-volume and water notation are replaced by explicit modern weights and volume. The historical jar covering is replaced by refrigeration or freezing, not presented as safe preservation.')
add('historical-95cac5255f40f3aedaa6c86a','Äppelmos (Slow-Reduced Apple Sauce)',16,85,'Sieved apples are cooked again with sugar until thick, preserving the source’s long reduction and moderately sweet ratio.',[apples(1000),water(500),sugar(375)],['Cut {{apples}} into small pieces. Put them in a large, heavy saucepan with {{water}} and bring to a gentle simmer.','Cook for 15–25 minutes, stirring occasionally, until completely soft. Press through a sieve into a clean saucepan.','Stir in {{sugar}} and simmer uncovered over low heat for 30–60 minutes, stirring frequently, until the sauce is thick enough to mound softly on a spoon. Watch closely near the end to prevent scorching.'],'Two equivalent Idun transcriptions are combined. A half-size batch retains the apple/water/sugar ratio, using prepared fruit weight. The historical chemical preservative and wax/fat/cognac sealing methods are omitted entirely; this adaptation requires refrigeration or freezing.')
add('historical-8788d6cca0f07cd02dbcbd7f','Clove-Spiced Apple Sauce',10,40,'Tart apples simmer with sugar and whole cloves, then are mashed into a strongly aromatic sauce.',[apples(1200),water(180),sugar(200),ing('cloves',8,'','whole cloves','Use 0.75 g ground cloves for a slightly different texture; do not strain out ground spice.')],['Cut {{apples}} into 2 cm pieces. Put them in a heavy saucepan with {{water}} and {{sugar}}.','Tie {{cloves}} in a small piece of food-safe cheesecloth and add to the pan, or count them carefully so all can be removed. Bring to a gentle simmer.','Cover loosely and cook for 20–30 minutes, stirring frequently, until the apples are very soft. Add a small splash of water if the bottom begins to dry.','Remove and discard the clove bundle or all whole cloves, then mash the fruit to the desired texture.'],'Eight source apples become 1200 g prepared fruit; one cup of sugar is assigned 200 g. The original eight cloves remain, with an explicit removal step to avoid leaving whole spices in the finished sauce.')
assert len(newids)==7
for old,new in merges.items():
 aliases[old]=dict(id=old,canonicalId=new,bodySha256=original(old)['bodySha256'],reason='Full ingredients and methods reviewed together: equivalent apple-sauce formula. Source credits retained; modern water/fruit weights and any removal of historical storage practices are disclosed in the canonical adaptation.')
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full source and formula reviewed; measured apple sauce and modern cold storage','repair-batch-006.py'))
for old in merges:db.execute('insert or replace into decisions values(?,?,?,?,?)',(old,aliases[old]['bodySha256'],'prepared-merge',aliases[old]['reason'],'repair-batch-006.py'))
db.commit()
print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))
